const menu=document.querySelector('#menu');menu?.addEventListener('click',()=>{const open=document.querySelector('nav').classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'Close':'Menu'});document.querySelector('#enquiry')?.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget);const text=`Hello NASAQ, I would like a quotation.\nName: ${data.get('name')}\nProject: ${data.get('type')}\nLocation: ${data.get('location')}\nDetails: ${data.get('details')}`;window.location.href='https://wa.me/971505334861?text='+encodeURIComponent(text)});
